clear global lpass% geomdir = fullfile('C:\Users\Peter.Damp2\Documents\ECG_simulation\STW\Data\geometries\');geomdir='/Users/peteroosterhoff/Documents/Werk/STW/Data/geometries/';beatlim=5; % limit number of beats per fileskipexisting=1; % when 1 will skip if file already existscasedir		='';% dirout=fullfile('.\results\');dirout=fullfile('/Users/peteroosterhoff/Documents/Werk/STW/Data/results/');% which leads should be used in the initial esitimateleadset='all';pwavecorflag=true; % true will use P-wave corrected versionaveragebeatflag=false; % when true take average beat as beat 0.sub=9;saveCase = 1;sinkScan= 0;doAtria=0;group = '';layfile='pig64.mla'; % default for pigstype='ventricles';if sub==7    subject='Pig07';    %     bsmdir=fullfile('C:\Users\Peter.Damp2\Documents\ECG_simulation\STW\Data\measurements\Pig07\Export\blind\');    bsmdir='/Users/peteroosterhoff/Documents/Werk/STW/Data/Pig07/Biosemi/export/';    dirout=['/Users/peteroosterhoff/Documents/Werk/STW/Data/results/' subject '/'];elseif sub==8    subject='Pig08';    bsmdir='/Users/peteroosterhoff/Documents/Werk/STW/Data/Pig08/Biosemi/export/Pacing/blind/';    dirout=['/Users/peteroosterhoff/Documents/Werk/STW/Data/results/' subject '/'];elseif sub==9    subject='Pig09';    %     bsmdir=fullfile('C:\Users\Peter.Damp2\Documents\ECG_simulation\STW\Data\measurements\Pig07\Export\blind\');    %     bsmdir='/Users/peteroosterhoff/Documents/Werk/STW/Data/Pig09/Biosemi/export/';    bsmdir='/Users/peteroosterhoff/Documents/Werk/STW/Data/Pig09/Biosemi/export/';    dirout=['/Users/peteroosterhoff/Documents/Werk/STW/Data/results/' subject '/'];elseif sub==10    subject='Pig10';    %     bsmdir=fullfile('C:\Users\Peter.Damp2\Documents\ECG_simulation\STW\Data\measurements\Pig07\Export\blind\');    bsmdir='/Users/peteroosterhoff/Documents/Werk/STW/Data/Pig10/BioSemi/export/';    dirout=['/Users/peteroosterhoff/Documents/Werk/STW/Data/results/' subject '/'];elseif sub==48   