         if ibeat                    savemat(fn, DATA.BSMOUTPWC(:,DATA.BEATS(ibeat):min(DATA.BEATS(ibeat+1),DATA.BEATS(ibeat)+750)));                    GEOM.BSM=DATA.BSMOUTPWC(:,DATA.BEATS(ibeat):min(DATA.BEATS(ibeat+1),DATA.BEATS(ibeat)+750));                elseif averagebeatflag                    savemat(fn,DATA.AVERAGEPWC);                    GEOM.BSM=DATA.AVERAGEPWC;                else                    continue                end                            else                if pwavecorflag                    warning('No P-wave corrected version available');                end                if ibeat                    savemat(fn, DATA.BSMOUT(:,DATA.BEATS(ibeat):min(DATA.BEATS(ibeat+1),DATA.BEATS(ibeat)+750)));                    GEOM.BSM=DATA.BSMOUT(:,DATA.BEATS(ibeat):min(DATA.BEATS(ibeat+1),DATA.BEATS(ibeat)+750));                elseif averagebeatflag                    savemat(fn,DATA.AVERAGE);                    GEOM.BSM=DATA.AVERAGE;                else                    continue                end            end%             bsmfile = fn;%             % Load all data from selected subject%             disp('===============================================================')%             disp(['Loading the ' type  ' of subject ' subject '  selected beat:' num2str(ibeat) ' from: ' bsmfiles(k).name])%             %             GEOM.LAY=loadmat(layfile);%             %             %             %             GEOM=invInit('subject',subject,'layfile',layfile,'bsm',bsmfile,'type',type,...%             %                 'anisotropyRatio',2.5,'group',group,'basedir',geomdir,'usemean',1);%             useLeads=1:size(GEOM.LAY,1) - 1;%             remove = DATA.remove;%             if length(remove)>length(useLeads)%                 remove = DATA.remove(1:64); % Pig09; fix for adding EGM, but not in lay file%                 display('Remove limited to 64 leads');%             end%             useLeads(remove ==1)=[];%             L= GEOM.LAY(2:end,:);%             for i=1:size(L,1)%                 L(i,3) = L(i,3) - sum(remove (1:i));%             end%             L(remove ==1,:)=[];%             LL=L;%             GEOM.LAY = [GEOM.LAY(1,:); L];%             %             GEOM = selectLeads(GEOM,useLeads,1);%             GEOM.BSM = zeromean(GEOM.BSM(useLeads,:));%             GEOM.subject=subject;%             figure(299);clf;plot(rms(GEOM.BSM));%             %               [GEOM.BSM,GEOM.spikeSamples]=removePacingSpike(GEOM.BSM);%             %             figure(299);hold on;plot(rms(GEOM.BSM),'r');%             %     savemat([bsmfile(1:end-4) '.selecg'],GEOM.BSM);%             %             figure(298);clf; showPatch(GEOM.TVER,GEOM.TITRI,GEOM.BSMall(:,find(rms(GEOM.BSM)==max(rms(GEOM.BSM)))));%             %             GEOM = prepare_geom(GEOM,[fn(1:end-7) '.spe'],2 );%             %             %             GEOM = prepare_geom_fixed(GEOM,[fn(1:end-7) '.spe'],2 );  % hard coded values%                     end        if ibeat>0 && DATA.SELBEATS(ibeat) % count new and existing beat, but not the average beat            beatcount=beatcount+1;            if beatcount>= beatlim                fprintf('Number of beats limited on %d\n',beatlim);                break            end        end    endend